#if ARENA_TESTS
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
namespace ChipArena.UnityConversion
{
    // The Siren zombies (owner 2026-10-12: "Sirens minions need to look more zombie like (Based on player models) ... We do have
    // the zombie mo-cap ones we could utilize ... They still use old model when entering through doors and vents~ Brutes can be
    // big muscle versions ... enter from the middle of the map by jumping down and creating a small slam effect on their
    // landing"): the zombie mocap tracks are the exporter's (SHA-256 per track) and only tracks are committed; every kind's
    // takes decode and phase; the drawn ankles of planted feet stay put at the authority's speeds (no foot sliding on the rig,
    // not just in the gait's bookkeeping); every captured blow lands on the take's impact exactly at LastAttack + hit; the
    // entrances (vent climb, door walk-in, dive) and the brute's jump-down pose the zombie model on the authority's entry
    // timeline and never the old bank clips; deaths fall the way they are pushed and lie on the floor; the drop's landing spot
    // and height come from the entry (map data), not coordinates; the slams' shake is bounded and gated; no allocation.
    internal static class ZombieMotionChecks
    {
        private static int count;
        private static void Check(bool ok,string what){if(!ok)throw new Exception("Zombie motion: "+what);count++;}
        private static string R(string root,string path)=>File.ReadAllText(Path.Combine(root,path));
        public static void Run(string root)
        {
            Tracks(root);Sets();Planted();Strikes();Entrances();Deaths();Drop(root);Shake();Allocation();Runtime(root);
            Console.WriteLine("PASS zombie motion ("+count+" checks: "+NativeZombieClips.Count+" tracks match the exporter's provenance, every kind's takes decode and phase, planted ankles still on the drawn rig at the authority's speeds, captured blows land on their impact at LastAttack + hit, vent climb, door walk-in, dive and jump-down on the zombie model, deaths on the floor, the drop from map data, bounded slam shake, no allocation, presentation-only runtime)");
        }
        // ---- the exporter's tracks, and nothing of the pack ----
        private static void Tracks(string root)
        {
            using var doc=JsonDocument.Parse(R(root,"tools/pack-zombie-provenance.json"));var prov=doc.RootElement.GetProperty("clips").EnumerateArray().ToDictionary(e=>e.GetProperty("clip").GetString());
            Check(doc.RootElement.GetProperty("channels").GetInt32()==CapturedClip.Channels&&prov.Count==NativeZombieClips.Count&&NativePackZombie.Keys.Length==NativeZombieClips.Count,"the provenance lists every clip");
            for(int i=0;i<NativeZombieClips.Count;i++)
            {
                var c=NativeZombieClips.Clip(i);string key="zombie/"+NativeZombieClips.Key(i);Check(c.Name==key&&prov.ContainsKey(key),key+" is in the provenance");var p=prov[key];
                Check(p.GetProperty("frames").GetInt32()==c.Frames&&p.GetProperty("fps").GetInt32()==c.Fps&&p.GetProperty("loop").GetBoolean()==c.Loop&&p.GetProperty("source").GetString()==c.Source,key+": size and source match");
                string sha=Convert.ToHexString(SHA256.HashData(Encoding.ASCII.GetBytes(c.Data))).ToLowerInvariant();Check(sha==p.GetProperty("sha256").GetString(),key+": the track is the exporter's output");
                var d=c.Decode();Check(d.All(MathUtil.Finite),key+": finite");Check(c.Duration>0,key+": has a duration");
                if(c.Loop&&!NativeZombieClips.Key(i).StartsWith("idle")&&!NativeZombieClips.Key(i).StartsWith("shamble")&&!NativeZombieClips.Key(i).StartsWith("jump"))
                {Check(NativeZombieClips.Speed(i)>0&&NativeZombieClips.LeftLift(i)>0&&NativeZombieClips.LeftLift(i)<1&&NativeZombieClips.RightLand(i)>=0&&NativeZombieClips.RightLand(i)<1,key+": a gait cycle with its speed and foot phases");
                 for(int k=0;k<CapturedClip.Channels;k++)Check(Math.Abs(d[k]-d[(c.Frames-1)*CapturedClip.Channels+k])<1e-6f,key+": the cycle closes");}
            }
            // Only the retargeted tracks are committed: no FBX, mesh, texture or audio of the pack in the Unity project.
            string gen=R(root,"Assets/ChipArena/Core/NativePackZombie.Generated.cs");Check(gen.StartsWith("// GENERATED by tools/export_pack_zombie.mjs")&&!gen.Contains("MCG_")&&!gen.Contains(".jpg"),"the generated file holds tracks only");
            foreach(var f in Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories))
            {
                string rel=f.Substring(root.Length).Replace('\\','/');if(rel.Contains("/bin/")||rel.Contains("/obj/")||rel.Contains("/Library/"))continue;
                Check(!rel.Contains("Zombie_27")&&!rel.Contains("MotusMan")&&!f.EndsWith(".fbx",StringComparison.OrdinalIgnoreCase),"no zombie pack file in the project ("+rel+")");
            }
        }
        // ---- every kind's takes ----
        private static void Sets()
        {
            foreach(int k in new[]{NativeHordeKinds.Shambler,NativeHordeKinds.Runner,NativeHordeKinds.Brute,NativeHordeKinds.Spitter,NativeHordeKinds.Bloater})
            {
                Check(NativeZombieMotion.Captured(k)&&NativeZombieMotion.Walks(k).Length>0&&NativeZombieMotion.Runs(k).Length>0&&NativeZombieMotion.Idles(k).Length>0,NativeHordeKinds.Ids[k]+" walks, runs and stands on the capture");
                var seen=new HashSet<int>();for(int id=10000;id<10400;id++){int w=NativeZombieMotion.Walk(k,NativeHordeKinds.Seed(id));Check(Array.IndexOf(NativeZombieMotion.Walks(k),w)>=0,"the walk is one of the kind's");seen.Add(w);}
                Check(seen.Count==NativeZombieMotion.Walks(k).Length,NativeHordeKinds.Ids[k]+": every walk take appears in a crowd");
                var st=NativeHordeKinds.ProposedRow(k);
                foreach(int c in NativeZombieMotion.Walks(k).Concat(NativeZombieMotion.Runs(k)))foreach(float v in new[]{.3f,st.walk,st.run}){float r=NativeZombieMotion.Rate(c,v,k);Check(r>=NativeZombieMotion.MinRate&&r<=NativeZombieMotion.MaxRate,"playback rate in range");}
            }
            Check(!NativeZombieMotion.Captured(NativeHordeKinds.Crawler),"the crawler's trot stays procedural");
            Check(NativeZombieMotion.Attack(NativeHordeKinds.Attack.Swipe,1,7)!=NativeZombieMotion.Attack(NativeHordeKinds.Attack.Swipe,-1,7)&&NativeZombieClips.Key(NativeZombieMotion.Attack(NativeHordeKinds.Attack.Swipe,1,7)).StartsWith("swipe-r")&&NativeZombieClips.Key(NativeZombieMotion.Attack(NativeHordeKinds.Attack.Swipe,-1,7)).StartsWith("swipe-l"),"a swipe plays the striking arm's take");
            Check(NativeZombieClips.Key(NativeZombieMotion.Attack(NativeHordeKinds.Attack.Smash,1,3)).StartsWith("smash")&&NativeZombieClips.Key(NativeZombieMotion.Attack(NativeHordeKinds.Attack.Lunge,1,3)).StartsWith("lunge")&&NativeZombieMotion.Attack(NativeHordeKinds.Attack.Spit,1,3)<0&&NativeZombieMotion.Attack(NativeHordeKinds.Attack.Belly,1,3)<0&&NativeZombieMotion.Attack(NativeHordeKinds.Attack.Pounce,1,3)<0,"the hammer, the lunge and the procedural spit, belly and pounce");
        }
        // ---- planted feet on the drawn rig: a planted ankle stays where it is in the world (each take, walk and run, turning) ----
        private static void Planted()
        {
            var pose=new CapturedRig.Pose();
            foreach(int k in new[]{NativeHordeKinds.Shambler,NativeHordeKinds.Runner,NativeHordeKinds.Brute})
            {
                var st=NativeHordeKinds.ProposedRow(k);
                foreach(var (set,speed) in new[]{(NativeZombieMotion.Walks(k),st.walk),(NativeZombieMotion.Runs(k),st.run)})foreach(int clip in set)foreach(float turn in new[]{0f,35f})
                {
                    int id=60000+k*1000;while(NativeZombieMotion.Walk(k,NativeHordeKinds.Seed(id))!=(set==NativeZombieMotion.Walks(k)?clip:NativeZombieMotion.Walk(k,NativeHordeKinds.Seed(id)))||NativeZombieMotion.Run(k,NativeHordeKinds.Seed(id))!=(set==NativeZombieMotion.Runs(k)?clip:NativeZombieMotion.Run(k,NativeHordeKinds.Seed(id))))id++;
                    var g=new NativeHordeGait();var f=new HordeMotionInput{Kind=k,Id=id,Seed=NativeHordeKinds.Seed(id),Health=1,AttackAge=float.NaN};var last=new Vector3[2];var air=new bool[2];float worst=0,worstDrawn=0;int steps=0,planted=0;Vector3 at=new Vector3(0,.85f,0);float yaw=0;
                    for(int i=0;i<420;i++)
                    {
                        float t=i/60f;yaw+=turn/60;float r=yaw*(float)Math.PI/180;var v=new Vector3((float)Math.Sin(r),0,(float)Math.Cos(r))*speed;at+=v/60;
                        f.Time=t;f.Root=at;f.Velocity=v;f.Yaw=yaw;f.Ground=0;g.Pose(f,pose);
                        for(int j=0;j<2;j++)
                        {
                            // The ankle as drawn: the posed joint turned by the presented yaw into the world.
                            var drawn=g.ToWorld(pose.WorldPosition[j==0?CapturedRig.LFoot:CapturedRig.RFoot],at);
                            if(i>90&&!air[j]&&!g.FootAir[j]){worst=Math.Max(worst,Vector3.Distance(last[j],g.FootWorld[j]));float d=new Vector2(drawn.X-g.FootWorld[j].X,drawn.Z-g.FootWorld[j].Z).Length();worstDrawn=Math.Max(worstDrawn,d);planted++;Check(Math.Abs(drawn.Y-NativeHordeGait.AnkleHeight)<.01f,"a planted ankle stands on the floor");}
                            if((g.Landed&(1<<j))!=0)steps++;last[j]=g.FootWorld[j];air[j]=g.FootAir[j];
                        }
                    }
                    string what=NativeHordeKinds.Ids[k]+" on "+NativeZombieClips.Key(clip)+" at "+speed+" m/s turning "+turn;
                    Check(worst<1e-4f,what+": planted feet never slide (worst "+worst+")");
                    Check(worstDrawn<.012f,what+": the drawn ankle of a planted foot is on its spot (worst "+worstDrawn.ToString("0.0000")+" m)");
                    Check(steps>=10&&planted>steps,what+": it steps on the take's beat ("+steps+" steps, "+planted+" planted frames)");
                }
            }
        }
        // ---- the captured blow lands on its impact at the authority's strike ----
        private static void Strikes()
        {
            var pose=new CapturedRig.Pose();
            foreach(int k in new[]{NativeHordeKinds.Shambler,NativeHordeKinds.Runner,NativeHordeKinds.Brute})
            {
                var st=NativeHordeKinds.ProposedRow(k);var attack=NativeHordeKinds.AttackOf(k,st.attack,false);
                foreach(bool crawlArmless in new[]{false,true})foreach(int side in new[]{1,-1})
                {
                    int lost=crawlArmless?2|4:0;float H=NativeHordeKinds.Strike(st.hit,false,lost),Rc=NativeHordeKinds.Recover(st.hit,st.cycle,false,lost);
                    var g=new NativeHordeGait();var f=new HordeMotionInput{Kind=k,Id=70000+k,Seed=NativeHordeKinds.Seed(70000+k),Health=1,AttackAge=float.NaN,Root=new Vector3(0,.85f,0),Attack=attack,Strike=H,Recover=Rc,Side=side,Lost=lost};
                    float t0=1;float prev=-1;
                    for(int i=0;i<=(int)((t0+Rc)*240);i++)
                    {
                        float t=i/240f;f.Time=t;f.AttackAge=t>=t0?t-t0:float.NaN;g.Pose(f,pose);if(t<t0)continue;
                        Check(g.AttackClip>=0,NativeHordeKinds.Ids[k]+": the blow plays its captured take");var c=NativeZombieClips.Clip(g.AttackClip);
                        Check(g.AttackClipTime>=prev-1e-5f,"the take never runs backward");prev=g.AttackClipTime;
                        if(Math.Abs(f.AttackAge-H)<1e-6f)Check(Math.Abs(g.AttackClipTime-c.Marks[2])<1e-5f,NativeHordeKinds.Ids[k]+": the take's impact is shown exactly at LastAttack + "+H);
                        if(f.AttackAge<H-1e-4f)Check(g.AttackClipTime<c.Marks[2],"the impact never shows before the strike");
                    }
                    // and at the strike itself, on the exact age:
                    f.Time=t0+H;f.AttackAge=H;g.Pose(f,pose);Check(Math.Abs(g.AttackClipTime-NativeZombieClips.Clip(g.AttackClip).Marks[2])<1e-5f,NativeHordeKinds.Ids[k]+": impact at the strike age");
                    float lead=Math.Min(NativeHordeGait.SwingLead(attack),H*.45f);f.AttackAge=H-lead;g.Pose(f,pose);Check(Math.Abs(g.AttackClipTime-NativeZombieClips.Clip(g.AttackClip).Marks[1])<1e-5f,NativeHordeKinds.Ids[k]+": the wind-up's peak held to the swing's lead");
                }
            }
            foreach(var key in new[]{"swipe-r1","swipe-l1","swipe-r2","swipe-l2","smash-1","smash-2","lunge-1","lunge-2"}){var c=NativeZombieClips.Clip(NativeZombieClips.Need(key));Check(c.Marks.Length==4&&c.Marks[0]<c.Marks[1]&&c.Marks[1]<c.Marks[2]&&c.Marks[2]<c.Marks[3]&&c.Marks[3]<=c.Duration+1e-4f,key+": marks [start, wind-up, impact, settled] in order");}
        }
        // ---- entrances on the zombie ----
        private static void Entrances()
        {
            var p=new CapturedRig.Pose();
            float prevChest=float.NegativeInfinity;
            for(int i=0;i<=78;i++)
            {
                float tau=i*.025f;var climb=NativeEntryRules.Climb(tau,1.95f);var c=new Vector3(0,climb.y,climb.z);NativeHordeGait.VentClimb(p,0,9,tau,c);
                Check(p.WorldPosition.All(v=>MathUtil.Finite(v.X)&&MathUtil.Finite(v.Y)&&MathUtil.Finite(v.Z)),"the climb is finite");
                float floor=NativeHordeGait.Floor-c.Y,chest=p.WorldPosition[CapturedRig.Chest].Y-floor;
                if(tau<=.3f)Check(chest<0,"in the shaft the chest is under the floor ("+tau+")");
                if(tau>=.6f&&tau<=1.2f)for(int h=0;h<2;h++){var hand=p.WorldPosition[h==0?CapturedRig.LHand:CapturedRig.RHand];Check(Math.Abs(hand.Y-(floor+.06f))<.08f&&hand.Z>NativeHordeGait.VentRim-c.Z-.05f,"hauling, its hands are on the floor past the rim ("+tau+")");}
                if(tau>=1.94f){float low=Math.Min(p.WorldPosition[CapturedRig.LFoot].Y,p.WorldPosition[CapturedRig.RFoot].Y)-floor;Check(low>-.05f&&low<.14f,"it ends standing on the floor ("+low+")");}
                prevChest=chest;
            }
            for(int i=0;i<=36;i++){float a=i*.025f;NativeHordeGait.Dive(p,0,5,a);Check(p.WorldPosition.All(v=>MathUtil.Finite(v.Y)),"the dive is finite");if(a>=.88f)Check(p.WorldPosition[CapturedRig.Head].Y<NativeHordeGait.Floor,"the dive ends in the shaft");}
            // The door: the wait plays the waking take, then the gait walks it in on planted steps.
            var g=new NativeHordeGait();var f=new HordeMotionInput{Kind=1,Id=71000,Seed=NativeHordeKinds.Seed(71000),Health=1,AttackAge=float.NaN,Entering=true,EntryWalk=.6f};int steps=0;var pose=new CapturedRig.Pose();
            for(int i=0;i<=168;i++){float t=i/60f;float u=Math.Clamp((t-.6f)/2f,0,1);f.Time=t;f.EntryAge=t;f.Root=new Vector3(0,.9f,-3.5f+3.5f*u);f.Velocity=new Vector3(0,0,t>.6f&&t<2.6f?3.5f/2f:0);f.Ground=0;g.Pose(f,pose);if(i>40)steps+=g.Landed!=0?1:0;if(t<.55f&&i>3)Check(g.Landed==0,"waiting, it does not step");}
            Check(steps>=3,"the door walk steps in ("+steps+")");
        }
        // ---- deaths ----
        private static void Deaths()
        {
            var p=new CapturedRig.Pose();
            foreach(int k in new[]{0,1,2,3})foreach(var push in new[]{new Vector2(0,-1),new Vector2(0,1),new Vector2(1,0),new Vector2(-1,0),Vector2.Zero})for(uint seed=1;seed<4;seed++)
            {
                var last=Vector3.Zero;
                for(int i=0;i<=46;i++)
                {
                    float a=i*.05f;NativeHordeGait.Death(p,k,seed,a,push);float low=p.Lowest();Check(Math.Abs(low-NativeHordeGait.Floor)<1e-3f,"a death lies on the floor, never through it ("+low+")");
                    float up=p.WorldPosition[CapturedRig.Head].Y-NativeHordeGait.Floor;
                    if(a>=NativeHordeGait.DownAt+.05f)Check(up<.8f,NativeHordeKinds.Ids[k]+": going down by "+NativeHordeGait.DownAt+" s ("+up+")");
                    if(a>=1.3f)Check(up<.55f,NativeHordeKinds.Ids[k]+": lying on the floor from 1.3 s, never kneeling or getting up ("+up+")");
                    if(i>0){float moved=Vector3.Distance(p.WorldPosition[CapturedRig.Head],last);Check(moved<.4f,"no pop between frames ("+moved+" m in .05 s)");}last=p.WorldPosition[CapturedRig.Head];
                }
                // The fall goes the way of the push.
                NativeHordeGait.Death(p,k,seed,2.3f,push);var head=p.WorldPosition[CapturedRig.Head];
                if(push.Y<0)Check(head.Z<-.15f,"pushed back, it falls back");if(push.Y>0)Check(head.Z>.15f,"pushed forward, it falls forward");
                if(push.X>0)Check(head.X>.15f,"pushed to its left, it falls to its left");if(push.X<0)Check(head.X<-.15f,"pushed to its right, it falls to its right");
            }
        }
        // ---- the brute's jump-down ----
        private static void Drop(string root)
        {
            var p=new CapturedRig.Pose();float h=NativeHordeDrop.DefaultHeight,span=NativeHordeDrop.Duration(h),land=NativeHordeDrop.LandAt(span);float prevLift=float.NaN;var prevPhase=NativeHordeDrop.Phase.Warn;
            for(int i=0;i<=(int)(span*120);i++)
            {
                float age=i/120f;bool shown=NativeHordeGait.Drop(p,7,age,span,h,out float lift,out var phase);
                Check(phase>=prevPhase,"the phases run in order");prevPhase=phase;
                Check(shown==(phase!=NativeHordeDrop.Phase.Warn),"only the warning is drawn without the brute");
                if(!float.IsNaN(prevLift)&&phase!=NativeHordeDrop.Phase.Warn)Check(Math.Abs(lift-prevLift)<.25f,"the fall is continuous");prevLift=lift;
                if(age<land-1e-3f)Check(lift>0,"it is in the air until the landing");else Check(lift==0,"it is on the floor from the landing");
                if(phase==NativeHordeDrop.Phase.Land)for(int j=0;j<2;j++)Check(Math.Abs(p.WorldPosition[j==0?CapturedRig.LFoot:CapturedRig.RFoot].Y-(NativeHordeGait.Floor+NativeHordeGait.AnkleHeight))<.012f,"landed, its feet are on the floor");
                Check(NativeHordeFx.DropMark(age,land,out _,out _,out _)==(age<=land+.02f),"the landing spot is marked until the touchdown");
            }
            Check(Math.Abs(NativeHordeDrop.LandAt(10)-(10-NativeHordeDrop.Recover))<1e-6f&&Math.Abs(span-(NativeHordeDrop.Warn+NativeHordeDrop.Leap+NativeHordeDrop.Fall(h)+NativeHordeDrop.Recover))<1e-5f,"the timeline: warn, leap, fall, recover");
            NativeHordeDrop.At(land-NativeHordeDrop.Fall(h)-.001f,span,h,out _,out float top);Check(Math.Abs(top-(h+NativeHordeDrop.Hop))<.01f,"the leap tops out at the drop height plus the hop");
            Check(NativeHordeFx.LandWave(0,out _,out _,out float a0)&&a0>.8f&&!NativeHordeFx.LandWave(-.01f,out _,out _,out _),"the landing slam starts at the touchdown, never before");
            Check(NativeHordeDrop.Is(new PveEntry{kind="drop"})&&!NativeHordeDrop.Is(new PveEntry{kind="vent"})&&!NativeHordeDrop.Is(null),"a drop is an entry of kind \"drop\"");
            // Map data, not coordinates: the landing point is the entry's, the height the entry's (or the default fall height).
            var pres=R(root,"Assets/ChipArena/Runtime/NativeHordeKindPresentation.cs");
            Check(pres.Contains("NativeHordeDrop.Is(a.Entry)")&&pres.Contains("float height=NativeHordeDrop.HeightOf(a.Entry,profile);var land=NativeArena.Vec(a.Entry.@exit.Position(0));"),"the drop lands on its entry's point at its entry's height");
            var source=R(root,"Assets/ChipArena/Core/NativeHordeDrop.cs");
            Check(source.Contains("e.height")&&source.Contains("e!=null"),"drop height comes from entry data with a legacy default");
            Check(NativeHordeDrop.HeightOf(new PveEntry{height=13})==13&&NativeHordeDrop.HeightOf(new PveEntry{height=7},NativeHordeDrop.Hulk)==7,"authored heights override both profiles");

        }
        // ---- the slams' camera shake: bounded, by distance, a kick only for a pilot in the disc ----
        private static void Shake()
        {
            var slots=new NativeHordeFx.Shake[NativeHordeFx.ShakeSlots];NativeHordeFx.AddShake(slots,new Vector3(0,0,0),1,.07f,12,0,5);NativeHordeFx.AddShake(slots,new Vector3(0,0,0),1,.07f,12,0,5);
            Check(slots.Count(s=>s.Live)==1,"the same slam shakes once");
            float far=NativeHordeFx.ShakeAt(slots,new Vector3(13,1.6f,0),1.1f,out float kick0).Length(),near=0;for(int i=1;i<20;i++)near=Math.Max(near,NativeHordeFx.ShakeAt(slots,new Vector3(1,1.6f,0),1+i*.01f,out _).Length());
            Check(far==0&&kick0==0&&near>0&&near<=.07f,"the shake reaches its range only and stays under its peak");
            Check(NativeHordeFx.ShakeAt(slots,new Vector3(1,1.6f,0),1+NativeHordeFx.ShakeSeconds+.01f,out _).Length()==0,"it is over after "+NativeHordeFx.ShakeSeconds+" s");
            NativeHordeFx.AddShake(slots,new Vector3(5,0,0),3,.09f,9,3.2f,6);float most=0;for(int i=0;i<30;i++){NativeHordeFx.ShakeAt(slots,new Vector3(5,1.6f,0),3+i*.01f,out float k);most=Math.Max(most,k);}Check(most>1&&most<=3.2f,"a pilot in the smash's disc gets the kick ("+most+")");
        }
        // ---- no allocation ----
        private static void Allocation()
        {
            var p=new CapturedRig.Pose();var g=new NativeHordeGait();var slots=new NativeHordeFx.Shake[NativeHordeFx.ShakeSlots];
            void Frame(int i)
            {
                float t=i/60f;var climb=NativeEntryRules.Climb(t%1.95f,1.95f);NativeHordeGait.VentClimb(p,0,3,t%1.95f,new Vector3(0,climb.y,climb.z));NativeHordeGait.Dive(p,0,3,t%.9f);
                NativeHordeGait.Drop(p,3,t%3,3,6.5f,out _,out _);NativeHordeGait.Death(p,i%3,(uint)(i%5),t%2.3f,new Vector2(i%2,1-i%2));
                var f=new HordeMotionInput{Kind=0,Id=72000,Seed=NativeHordeKinds.Seed(72000),Time=t,Root=new Vector3(0,.9f,t),Velocity=new Vector3(0,0,1),Health=1,AttackAge=float.NaN,Entering=true,EntryAge=t%2,EntryWalk=.6f};g.Pose(f,p);
                NativeHordeFx.ShakeAt(slots,Vector3.Zero,t,out _);NativeHordeFx.DropMark(t%3,2,out _,out _,out _);NativeHordeFx.LandWave(t%1,out _,out _,out _);for(int k=0;k<NativeHordeFx.SlamDust;k++)NativeHordeFx.SlamPuff(3,k,t%1,2,out _,out _,out _);for(int k=0;k<NativeHordeFx.Cracks;k++)NativeHordeFx.Crack(3,k,t%1.6f,2,out _,out _,out _);
            }
            for(int i=0;i<300;i++)Frame(i);long before=GC.GetAllocatedBytesForCurrentThread();for(int i=300;i<1500;i++)Frame(i);long used=GC.GetAllocatedBytesForCurrentThread()-before;
            Check(used==0,"no allocation per frame over 1200 frames of entrances, drops, deaths and shakes ("+used+" bytes)");
        }
        // ---- the runtime: the zombie paths are the presentation's only, hooked where the adds are drawn ----
        private static void Runtime(string root)
        {
            var p=R(root,"Assets/ChipArena/Runtime/NativeHordeKindPresentation.cs");
            foreach(var old in new[]{"horde-0-vent","horde-0-door","horde-0-cell","horde-0-dive"})Check(!p.Contains(old),"the entrances never play the old bank clip "+old);
